function videoThumbError(img){const id=img.dataset.videoId||img.closest("[data-video-preview]")?.dataset.videoPreview;const step=Number(img.dataset.thumbStep||0);const candidates=[`https://i.ytimg.com/vi/${id}/hqdefault.jpg`,`https://i.ytimg.com/vi/${id}/mqdefault.jpg`,`https://i.ytimg.com/vi/${id}/default.jpg`];if(step<candidates.length){img.dataset.thumbStep=String(step+1);img.src=candidates[step];return;}const frame=img.closest(".video-frame");if(frame){frame.classList.add("preview-unavailable");img.remove();}}
function videoCard(v,i){return `<article class="video-card" data-video-card data-video-text="${(v.join(" ")).toLowerCase()}"><div class="video-frame video-preview" data-video-preview="${v[1]}"><img data-video-id="${v[1]}" data-thumb-step="1" src="https://i.ytimg.com/vi/${v[1]}/hqdefault.jpg" alt="Vista previa: ${v[0]}" loading="lazy" onerror="videoThumbError(this)"><button class="video-play" type="button" data-play-video="${v[1]}" data-video-title="${v[0]}">▶ <span>Reproducir video</span></button><div class="preview-fallback">Vista previa no disponible. Puedes abrir el video en YouTube.</div></div><div class="video-info"><h3>${v[0]}</h3><p>${v[2]}</p><a href="https://www.youtube.com/watch?v=${v[1]}" target="_blank" rel="noopener">Abrir video en YouTube ↗</a></div></article>`}
function theoryPage(){const all=getTheoryModules();return `${pageIntro("CONOCIMIENTO Y RESPETO","Aprende sobre LSEC","Conservamos los módulos iniciales y añadimos historia documentada, educación, gramática, ortografía, dactilología, cultura y recursos. Abre cada tema para leerlo completo.",`${all.length} módulos`)}
<div class="theory-grid">${all.map((t,i)=>`<button class="theory-card theory-button" data-theory="${i}"><span class="num">${t[0]} / APRENDE</span><h3>${t[1]}</h3><p>${t[2]}</p><span class="theory-more">Leer módulo completo →</span></button>`).join("")}</div>
<div class="section-head"><div><h2>Línea histórica resumida</h2><p>Hitos documentados en publicaciones y fuentes ecuatorianas.</p></div></div>
<div class="timeline">
 <article><strong>1940</strong><p>Enriqueta Santillán inicia actividades docentes con niños sordos en Quito.</p></article>
 <article><strong>1952</strong><p>Se funda el Instituto Mariana de Jesús, que atendía a niños con discapacidad visual y auditiva.</p></article>
 <article><strong>1962</strong><p>Se organiza el Instituto Nacional de Audición y Lenguaje (INAL) en Quito.</p></article>
 <article><strong>1980s</strong><p>El proyecto Mano a Mano registra vocabulario utilizado por comunidades sordas.</p></article>
 <article><strong>1986</strong><p>FENASEC obtiene personería jurídica, según la historia institucional de la federación.</p></article>
 <article><strong>1988</strong><p>Se publica una guía con fotografías, dibujos y glosas en español.</p></article>
 <article><strong>2012</strong><p>Se publica el Diccionario Oficial de LSEC en dos tomos, con 4.363 entradas según el Atlas Sordo.</p></article>
 <article><strong>1992</strong><p>FENASEC señala que ese año se alcanzó el reconocimiento oficial que la federación venía promoviendo.</p></article>
 <article><strong>Actualidad</strong><p>CONADIS, FENASEC y UTI impulsan el diccionario web Gabriel Román con miles de entradas y videos.</p></article>
</div>
<div class="resource-list">${resource("FENASEC · Historia de la federación","Antecedentes, asociaciones y dirigentes del movimiento sordo ecuatoriano.","https://fenasec-ecu.wixsite.com/fenasec/historia")}${resource("Atlas Sordo · Ecuador","Historia educativa, publicaciones y cronología de la comunidad sorda.","https://www.cultura-sorda.org/ecuador-atlas-sordo/")}${resource("CONADIS · Diccionario Gabriel Román","Diccionario web con gráficos y videos explicativos.",OFFICIAL_DICT)}</div>
<div class="notice">Nota histórica: las fuentes pueden presentar fechas distintas para algunos antecedentes comunitarios. La LSEC no tiene un fundador individual conocido: es una lengua desarrollada por sus usuarios y comunidades a lo largo del tiempo. FENASEC sitúa un club de personas sordas en Quito en 1958, mientras que el Atlas Sordo registra agrupaciones desde 1966; por eso se informa la diferencia en vez de presentar una fecha única como indiscutible.</div>`}
function activities(){const q=activityQuestions[activityIndex];return `${pageIntro("PRACTICA LO APRENDIDO","Actividades interactivas","Responde, recibe una explicación y avanza a la siguiente pregunta. Puedes reiniciar el reto cuando quieras.","Aprender y poner en práctica")}
<div class="activity-box"><div class="question-count">${q.category.toUpperCase()} · ${q.type.toUpperCase()} · PREGUNTA ${activityIndex+1} DE ${activityQuestions.length} · PUNTAJE ${score}</div><div class="progress"><span style="width:${(activityIndex/activityQuestions.length)*100}%"></span></div><div class="question-text">${q.q}</div><div class="answer-list">${q.a.map((a,i)=>`<button class="answer-btn" data-answer="${i}" ${answered?"disabled":""}>${String.fromCharCode(65+i)}. ${a}</button>`).join("")}</div><div class="feedback" id="feedback">${answered?q.why:"Elige una respuesta para continuar."}</div><div class="button-row"><button class="btn btn-primary" id="nextQuestion" ${answered?"":"disabled"}>${activityIndex===activityQuestions.length-1?"Ver resultado":"Siguiente pregunta →"}</button><button class="btn btn-light" id="restartQuiz">Reiniciar reto</button></div></div>
<div class="section-head"><div><h2>Retos de cultura e inclusión</h2><p>Practica cómo reconocer barreras, responder con respeto y construir una comunidad educativa accesible.</p></div></div>
<div class="activity-learning-grid">
 <article class="activity-learning-card"><span class="activity-kicker">RETO 01 · MITOS Y REALIDADES</span><h3>¿Verdadero o falso?</h3><p>Las lenguas de señas son universales y todas las personas sordas utilizan exactamente la misma.</p><div class="activity-choice-row"><button class="btn btn-light" data-mini-choice="myth" data-correct="false" data-feedback="¡Correcto! Las lenguas de señas varían entre países y comunidades; también existen diferencias individuales y regionales.">Falso</button><button class="btn btn-light" data-mini-choice="myth" data-correct="true" data-feedback="No es correcto. Las lenguas de señas no son universales: tienen historias, vocabularios y estructuras propias.">Verdadero</button></div><p class="mini-feedback" data-mini-feedback="myth" aria-live="polite">Selecciona una respuesta para comprobar lo aprendido.</p></article>
 <article class="activity-learning-card"><span class="activity-kicker">RETO 02 · SITUACIONES COTIDIANAS</span><h3>¿Qué harías en esta situación?</h3><p>En un trabajo grupal, una compañera sorda participa en LSEC y el equipo no sabe cómo comunicarse. ¿Cuál sería una buena primera acción?</p><div class="activity-choice-stack"><button class="answer-btn" data-mini-choice="scenario" data-correct="false" data-feedback="Excluir a alguien impide su participación y no resuelve la barrera de comunicación.">Continuar la reunión sin incluirla.</button><button class="answer-btn" data-mini-choice="scenario" data-correct="true" data-feedback="¡Muy bien! Lo adecuado es dirigirse a ella, preguntarle respetuosamente cómo prefiere comunicarse y buscar apoyos accesibles para que participe.">Preguntarle cómo prefiere comunicarse y acordar apoyos para incluirla.</button><button class="answer-btn" data-mini-choice="scenario" data-correct="false" data-feedback="Gritar no garantiza comprensión. Es mejor preguntar qué forma de comunicación prefiere y mantener una actitud respetuosa.">Gritar para que pueda entender.</button></div><p class="mini-feedback" data-mini-feedback="scenario" aria-live="polite">Elige la respuesta más inclusiva.</p></article>
 <article class="activity-learning-card"><span class="activity-kicker">RETO 03 · RELACIONA CONCEPTOS</span><h3>Une cada concepto con su significado</h3><p><strong>¿Cómo se relacionan?</strong> Lee cada concepto de la izquierda y su significado correspondiente a la derecha. Cada fila ya muestra una pareja correcta; recórrelas una por una.</p><div class="concept-match-list" style="display:grid;gap:10px"><div style="display:grid;grid-template-columns:minmax(110px, .8fr) 2fr;gap:10px;align-items:start;padding:12px;background:#f4f8f5;border-radius:12px"><strong>Accesibilidad</strong><span>Condiciones, recursos y ajustes que permiten acceder a información, espacios y actividades.</span></div><div style="display:grid;grid-template-columns:minmax(110px, .8fr) 2fr;gap:10px;align-items:start;padding:12px;background:#f4f8f5;border-radius:12px"><strong>Identidad sorda</strong><span>Manera en que una persona puede reconocerse y relacionarse con una lengua, comunidad y experiencias culturales.</span></div><div style="display:grid;grid-template-columns:minmax(110px, .8fr) 2fr;gap:10px;align-items:start;padding:12px;background:#f4f8f5;border-radius:12px"><strong>Inclusión</strong><span>Participación real de todas las personas, eliminando barreras y ofreciendo apoyos necesarios.</span></div><div style="display:grid;grid-template-columns:minmax(110px, .8fr) 2fr;gap:10px;align-items:start;padding:12px;background:#f4f8f5;border-radius:12px"><strong>Respeto comunicativo</strong><span>Preguntar y respetar cómo prefiere comunicarse cada persona, sin imponer una sola forma.</span></div></div></article>
 <article class="activity-learning-card"><span class="activity-kicker">RETO 04 · REFLEXIONA</span><h3>Piensa en tu entorno escolar</h3><p>Lee las preguntas y conversa con tu grupo. Puedes anotar tus ideas en tu cuaderno.</p><ul class="reflection-prompts"><li>¿Qué barreras de comunicación podrían aparecer durante una clase?</li><li>¿Qué podría hacer el curso para que todas las personas participen?</li><li>¿Por qué es importante aprender directamente de usuarios y docentes competentes en LSEC?</li></ul><details><summary>Ver una orientación para reflexionar</summary><p>Una escuela inclusiva identifica las barreras antes de que excluyan a alguien. Puede ofrecer información visual, materiales accesibles, turnos claros de participación y recursos de comunicación adecuados, consultando siempre a las personas involucradas.</p></details></article>
 <article class="activity-learning-card activity-commitment-card"><span class="activity-kicker">RETO 05 · NUESTRO COMPROMISO</span><h3>Acciones para una escuela más inclusiva</h3><p>Marca las acciones que puedes poner en práctica en el aula y en tu vida diaria.</p><label class="commitment-item"><input type="checkbox"> Preguntar con respeto qué forma de comunicación prefiere cada persona.</label><label class="commitment-item"><input type="checkbox"> Compartir recursos de LSEC de origen ecuatoriano y verificar su calidad.</label><label class="commitment-item"><input type="checkbox"> Evitar burlas, imitaciones o comentarios que desvaloricen una lengua o identidad.</label><label class="commitment-item"><input type="checkbox"> Procurar que la información importante también esté disponible por escrito o de forma visual.</label><label class="commitment-item"><input type="checkbox"> Escuchar las propuestas de las personas sordas al planificar actividades.</label><p class="commitment-note">Este compromiso es personal y no se guarda en una cuenta: puedes revisarlo y conversarlo en clase.</p></article>
 <article class="activity-learning-card"><span class="activity-kicker">RETO 06 · DETECTA LA BARRERA</span><h3>¿Qué dificulta la participación?</h3><p>En clase, las instrucciones importantes se dan solo de forma oral y no hay apoyos visuales. ¿Qué barrera aparece?</p><div class="activity-choice-stack"><button class="answer-btn" data-mini-choice="barrier" data-correct="true" data-feedback="¡Correcto! La información presentada por un solo canal puede dejar fuera a quienes necesitan o prefieren apoyos visuales.">La información no está disponible en un formato visual complementario.</button><button class="answer-btn" data-mini-choice="barrier" data-correct="false" data-feedback="La barrera está en cómo se presenta la información, no en la capacidad de participar del estudiante.">El estudiante no quiere aprender.</button></div><p class="mini-feedback" data-mini-feedback="barrier" aria-live="polite">Selecciona una respuesta.</p></article>
 <article class="activity-learning-card"><span class="activity-kicker">RETO 07 · COMUNICACIÓN RESPETUOSA</span><h3>Antes de ayudar, pregunta</h3><p>Quieres conversar con una persona sorda, pero no sabes qué forma de comunicación prefiere. ¿Qué haces?</p><div class="activity-choice-stack"><button class="answer-btn" data-mini-choice="respect" data-correct="true" data-feedback="¡Así es! Preguntar evita suposiciones y reconoce la autonomía de cada persona.">Preguntarle cómo prefiere comunicarse.</button><button class="answer-btn" data-mini-choice="respect" data-correct="false" data-feedback="No debemos asumir que todas las personas prefieren el mismo método de comunicación.">Suponer que todas las personas prefieren leer los labios.</button></div><p class="mini-feedback" data-mini-feedback="respect" aria-live="polite">Selecciona una respuesta.</p></article>
 <article class="activity-learning-card"><span class="activity-kicker">RETO 08 · PARTICIPACIÓN EN EQUIPO</span><h3>Una decisión entre todos</h3><p>El curso organiza una exposición accesible. ¿Cuál es la mejor manera de planificarla?</p><div class="activity-choice-stack"><button class="answer-btn" data-mini-choice="team" data-correct="false" data-feedback="Decidir sin consultar puede crear apoyos que no respondan a las necesidades reales.">Decidir todo sin consultar a las personas involucradas.</button><button class="answer-btn" data-mini-choice="team" data-correct="true" data-feedback="¡Correcto! Escuchar a las personas involucradas ayuda a elegir apoyos útiles y respetuosos.">Consultar a quienes participarán y acordar los apoyos.</button></div><p class="mini-feedback" data-mini-feedback="team" aria-live="polite">Selecciona una respuesta.</p></article>
 <article class="activity-learning-card"><span class="activity-kicker">RETO 09 · VERDADERO O FALSO</span><h3>Aprender también es respetar</h3><p>Aprender algunas señas básicas significa que ya se puede interpretar profesionalmente cualquier conversación en LSEC.</p><div class="activity-choice-row"><button class="btn btn-light" data-mini-choice="interpreter" data-correct="false" data-feedback="¡Correcto! Conocer algunas señas es un primer acercamiento; la interpretación requiere formación y competencia específicas.">Falso</button><button class="btn btn-light" data-mini-choice="interpreter" data-correct="true" data-feedback="No es correcto. La interpretación profesional exige preparación y dominio lingüístico.">Verdadero</button></div><p class="mini-feedback" data-mini-feedback="interpreter" aria-live="polite">Selecciona una respuesta.</p></article>
 <article class="activity-learning-card"><span class="activity-kicker">RETO 10 · AULA ACCESIBLE</span><h3>Elige una mejora concreta</h3><p>¿Cuál de estas acciones puede ayudar a que más estudiantes sigan las actividades de clase?</p><div class="activity-choice-stack"><button class="answer-btn" data-mini-choice="classroom" data-correct="true" data-feedback="¡Muy bien! Combinar explicaciones con esquemas e instrucciones escritas ofrece más de una vía para acceder a la información.">Acompañar las explicaciones con esquemas e instrucciones escritas.</button><button class="answer-btn" data-mini-choice="classroom" data-correct="false" data-feedback="La accesibilidad no se logra quitando información o reduciendo oportunidades de participación.">Evitar entregar instrucciones para que todos adivinen qué hacer.</button></div><p class="mini-feedback" data-mini-feedback="classroom" aria-live="polite">Selecciona una respuesta.</p></article>
</div>
<div class="section-head"><div><h2>Sigue aprendiendo</h2><p>Relaciona los retos con los demás recursos de la plataforma.</p></div></div><div class="feature-grid">${feature("♡","Cultura e inclusión","Conoce la cultura, los derechos y la comunicación respetuosa.","cultura")}${feature("▷","Ver videoteca","Continúa practicando con tutoriales de LSEC.","videoteca")}${feature("▤","Aprende LSEC","Repasa conceptos y características de la lengua.","teoria")}</div>`}
function cultura(){return `${pageIntro("PERSONAS, LENGUA Y COMUNIDAD","Cultura e inclusión","Conoce la cultura, la identidad, los derechos y las experiencias de la comunidad sorda. Esta sección propone comprender la inclusión desde el respeto y la participación, con especial atención al contexto ecuatoriano.","Comprender para incluir")}
<div class="culture-banner"><div><div class="eyebrow" style="color:#e7c77e">COMUNICACIÓN PARA TODOS</div><h2>La inclusión se construye en comunidad.</h2><p>Reconocer la lengua y cultura de las personas sordas significa respetar sus formas de comunicación, promover su participación y escuchar sus propias experiencias. La LSEC es una lengua viva y su comunidad debe tener un papel central en su enseñanza y difusión.</p><a class="btn btn-light" href="https://fenasec-ecu.wixsite.com/fenasec/bienvenido-a-web" target="_blank" rel="noopener">Conocer FENASEC ↗</a></div><img src="assets/images/inclusion-illustration.svg" alt="Ilustración decorativa de personas diversas compartiendo y comunicándose"></div>
<div class="section-head"><div><h2>Explora los temas</h2><p>Abre cada tema para conocer sus ideas principales y conversar sobre cómo aplicarlas en la vida diaria.</p></div></div>
<div class="culture-topic-grid">
<article class="culture-topic"><div class="culture-topic-icon">◉</div><span class="activity-kicker">IDENTIDAD Y COMUNIDAD</span><h3>Cultura e identidad sorda</h3><p>La cultura sorda reúne experiencias, formas de encuentro, expresiones artísticas, asociaciones y prácticas compartidas por personas sordas. No es idéntica para todos: cada persona construye su identidad de manera propia.</p><details><summary>Leer contenido completo</summary><p>Para muchas personas sordas, la lengua de señas es un elemento central de comunicación, pertenencia y transmisión cultural. Los encuentros comunitarios, las organizaciones, el arte visual, el teatro, el deporte y las redes de apoyo crean espacios donde se comparten experiencias y conocimientos. Es importante evitar pensar en la comunidad sorda como un grupo homogéneo: existen diferencias de edad, región, trayectoria educativa, preferencias lingüísticas y experiencias personales. La mejor manera de conocer esta cultura es acercarse a sus integrantes, reconocer sus voces y respetar cómo cada persona se identifica.</p><h4>Para conversar en clase</h4><ul><li>¿Por qué una lengua también puede ser parte de una identidad cultural?</li><li>¿Cómo podemos conocer la cultura sorda sin recurrir a estereotipos?</li><li>¿Por qué es importante que las personas sordas cuenten sus propias experiencias?</li></ul></details></article>
<article class="culture-topic"><div class="culture-topic-icon">⚖</div><span class="activity-kicker">DERECHOS Y PARTICIPACIÓN</span><h3>Derechos e igualdad</h3><p>La igualdad no consiste en ofrecer exactamente lo mismo a todos, sino en eliminar barreras y proporcionar los apoyos necesarios para que cada persona pueda ejercer sus derechos.</p><details><summary>Leer contenido completo</summary><p>Las personas sordas tienen derecho a la educación, la información, la participación social, la cultura y la comunicación accesible. La Convención sobre los Derechos de las Personas con Discapacidad reconoce la importancia de las lenguas de señas, la identidad lingüística de las personas sordas y los ajustes que permiten la participación. En Ecuador, la Constitución, la Ley Orgánica de Discapacidades y otras normas contienen disposiciones relacionadas con igualdad, accesibilidad y educación. La aplicación concreta de estos derechos requiere planificación, recursos, formación y consulta a las personas involucradas. La accesibilidad no es un favor: forma parte del respeto a la dignidad y a los derechos humanos.</p><h4>Para conversar en clase</h4><ul><li>¿Qué diferencia existe entre igualdad y equidad?</li><li>¿Qué información escolar debería estar disponible en formatos accesibles?</li><li>¿Qué barreras pueden impedir que una persona participe en igualdad de condiciones?</li></ul></details></article>
<article class="culture-topic"><div class="culture-topic-icon">◎</div><span class="activity-kicker">CONVIVENCIA</span><h3>Comunicación respetuosa</h3><p>La comunicación inclusiva comienza por reconocer las preferencias de cada persona y evitar suposiciones sobre cómo debe comunicarse.</p><details><summary>Leer contenido completo</summary><p>Cuando quieras iniciar una conversación, procura que la persona note tu presencia sin asustarla, colócate frente a ella y mantén visibles el rostro y las manos. Si no conoces LSEC, puedes preguntar de manera respetuosa qué recurso prefiere: escritura, lectura labial, interpretación u otra alternativa. No todas las personas sordas utilizan los mismos apoyos. Habla con naturalidad, no grites ni exageres los movimientos de la boca. Si no comprendes algo, dilo con respeto y pide que lo repita o lo explique de otra manera. En una conversación grupal, facilita los turnos y evita que varias personas hablen al mismo tiempo. Cuando haya una persona intérprete, dirige la comunicación a la persona sorda y no al intérprete.</p><h4>Para conversar en clase</h4><ul><li>¿Por qué es mejor preguntar antes de asumir cómo comunicarse?</li><li>¿Qué cambios sencillos mejorarían una conversación grupal?</li><li>¿Qué actitudes pueden hacer que alguien se sienta excluido?</li></ul></details></article>
<article class="culture-topic"><div class="culture-topic-icon">⌂</div><span class="activity-kicker">COMUNIDAD EDUCATIVA</span><h3>Inclusión en San Agustín</h3><p>Una institución inclusiva promueve que estudiantes, docentes y familias comprendan la diversidad y participen en la construcción de entornos accesibles.</p><details><summary>Leer contenido completo</summary><p>En la Unidad Educativa San Agustín, fomentar el conocimiento de la LSEC puede ser un punto de partida para conversar sobre accesibilidad y respeto. La inclusión se construye con acciones concretas: organizar actividades con instrucciones visuales, compartir materiales con anticipación, cuidar la iluminación, respetar los turnos de participación y consultar qué apoyos se necesitan. Aprender vocabulario básico puede abrir oportunidades de acercamiento, pero no convierte automáticamente a alguien en intérprete ni reemplaza la enseñanza formal. Los docentes pueden incorporar recursos ecuatorianos verificados y promover proyectos donde las personas sordas y sus organizaciones sean consultadas y reconocidas como referentes.</p><h4>Para conversar en clase</h4><ul><li>¿Qué podría hacer nuestro curso para promover el respeto por la LSEC?</li><li>¿Qué cambios harían más accesible una exposición o acto escolar?</li><li>¿Cómo podemos asegurarnos de que las propuestas respondan a necesidades reales?</li></ul></details></article>
<article class="culture-topic"><div class="culture-topic-icon">✦</div><span class="activity-kicker">REFERENTES Y MEMORIA</span><h3>Personas e historias inspiradoras</h3><p>Las historias de personas sordas permiten reconocer aportes en educación, cultura, deporte, arte, liderazgo y defensa de derechos.</p><details><summary>Leer contenido completo</summary><p>La historia de la comunidad sorda no debe contarse únicamente desde instituciones oyentes. Es importante investigar testimonios, publicaciones, asociaciones y referentes que hayan contribuido a la organización comunitaria, la educación y la difusión de la LSEC. En Ecuador, FENASEC y las asociaciones afiliadas son fuentes relevantes para conocer procesos colectivos y liderazgos. Al presentar una biografía, verifica el nombre, los aportes, las fechas y la fuente; evita atribuir a una sola persona la creación de una lengua que se desarrolla en comunidad. También se pueden incluir historias locales de estudiantes, docentes, artistas y profesionales sordos, siempre con su consentimiento y respetando cómo desean ser presentados.</p><h4>Para conversar en clase</h4><ul><li>¿Por qué es importante escuchar las historias contadas por personas sordas?</li><li>¿Qué datos debemos comprobar antes de publicar una biografía?</li><li>¿Cómo reconocer aportes colectivos y no solo individuales?</li></ul></details></article>
<article class="culture-topic"><div class="culture-topic-icon">♡</div><span class="activity-kicker">RESPONSABILIDAD COMPARTIDA</span><h3>Nuestro compromiso con la inclusión</h3><p>La inclusión se demuestra en decisiones cotidianas: escuchar, consultar, facilitar la participación y corregir prácticas que generan barreras.</p><details><summary>Leer contenido completo</summary><p>El compromiso con la inclusión no se limita a una fecha conmemorativa ni a aprender unas cuantas señas. Implica reconocer la diversidad, evitar burlas y prejuicios, compartir información accesible y dar espacio a las personas sordas para expresar sus preferencias y participar en decisiones. También supone aprender de fuentes ecuatorianas confiables, reconocer los límites de nuestro conocimiento y no enseñar como correcta una seña que no haya sido verificada. En el colegio, cada curso puede identificar una barrera, proponer una mejora realista y revisar si esa acción ayudó. Los cambios sostenibles nacen del respeto, la colaboración y la continuidad.</p><h4>Para conversar en clase</h4><ul><li>¿Qué compromiso concreto podemos asumir como curso?</li><li>¿Cómo sabremos si una acción realmente mejora la participación?</li><li>¿Por qué la inclusión debe mantenerse durante todo el año?</li></ul></details></article>
</div>
<div class="culture-resources"><div class="section-head"><div><h2>Fuentes para seguir aprendiendo</h2><p>Consulta organizaciones y materiales que permiten conocer la realidad ecuatoriana desde fuentes cercanas a la comunidad.</p></div></div><div class="resource-list">${resource("FENASEC · Federación Nacional de Personas Sordas del Ecuador","Organización y participación de la comunidad sorda ecuatoriana.","https://fenasec-ecu.wixsite.com/fenasec/bienvenido-a-web")}${resource("Atlas Sordo · Ecuador","Información histórica, educativa y cultural sobre la comunidad sorda.","https://www.cultura-sorda.org/ecuador-atlas-sordo/")}${resource("CONADIS · Diccionario Gabriel Román","Recurso ecuatoriano para consultar vocabulario y videos de LSEC.",OFFICIAL_DICT)}</div></div>`}
function proyecto(){return `${pageIntro("SOBRE ESTA INICIATIVA","LSEC San Agustín","Una plataforma educativa de la Unidad Educativa San Agustín para enseñar, acercar y fomentar el aprendizaje de la Lengua de Señas Ecuatoriana, promoviendo una comunidad escolar más informada, respetuosa e inclusiva.","Proyecto educativo institucional")}
<div class="section-head"><div><h2>¿De qué trata este proyecto?</h2><p>Una iniciativa educativa para aprender, compartir y practicar LSEC dentro de la comunidad San Agustín.</p></div></div>
<div class="theory-grid">
<article class="theory-card"><span class="num">PROPÓSITO PRINCIPAL</span><h3>Enseñar y fomentar la LSEC</h3><p>El proyecto busca acercar la Lengua de Señas Ecuatoriana a estudiantes, docentes y demás integrantes de la Unidad Educativa San Agustín. Su propósito es ofrecer un espacio claro y amigable para conocer la lengua, aprender vocabulario, observar recursos audiovisuales y comprender por qué la comunicación accesible es importante en la convivencia escolar. No pretende reemplazar la enseñanza especializada ni la participación de personas sordas; quiere despertar interés, facilitar el primer acercamiento y promover el respeto por la comunidad sorda ecuatoriana.</p></article>
<article class="theory-card"><span class="num">IDENTIDAD INSTITUCIONAL</span><h3>Unidad Educativa San Agustín</h3><p>LSEC San Agustín se plantea como un recurso educativo vinculado a la identidad y a la vida escolar de la institución. La propuesta toma como referencia a la Unidad Educativa San Agustín y su comunidad educativa, y busca que el aprendizaje de la LSEC pueda integrarse en clases, proyectos, exposiciones, actividades colaborativas y acciones de sensibilización. Sitio institucional: <a href="https://www.sanagustin.edu.ec/" target="_blank" rel="noopener">sanagustin.edu.ec ↗</a>.</p></article>
<article class="theory-card"><span class="num">DESTINATARIOS</span><h3>¿A quién está dedicado?</h3><p>Está dirigido principalmente a los estudiantes de la Unidad Educativa San Agustín, así como a docentes, autoridades, familias y a toda persona de la comunidad escolar que desee aprender. Se dedica de manera especial a las personas sordas del Ecuador, cuya lengua, cultura, historia y participación inspiran esta iniciativa. También busca motivar a quienes todavía no conocen la LSEC a dar sus primeros pasos con curiosidad, humildad y respeto.</p></article>
<article class="theory-card"><span class="num">OBJETIVOS EDUCATIVOS</span><h3>¿Qué queremos conseguir?</h3><p>Facilitar el conocimiento básico de la LSEC; despertar interés por continuar aprendiendo; difundir recursos ecuatorianos; reconocer que las lenguas de señas son lenguas naturales y no gestos universales; promover actitudes de respeto; y contribuir a que la comunicación inclusiva forme parte de la cultura escolar. El proyecto también busca que los estudiantes desarrollen habilidades de investigación, selección responsable de fuentes y trabajo colaborativo.</p></article>
<article class="theory-card"><span class="num">METODOLOGÍA</span><h3>Aprender explorando</h3><p>La plataforma organiza el contenido en módulos de aprendizaje, abecedario, videoteca, actividades y recursos sobre cultura e inclusión. Los estudiantes pueden avanzar a su propio ritmo, revisar explicaciones, observar videos y conversar sobre lo aprendido en el aula. Los docentes pueden utilizarla como apoyo para introducir temas, proyectar materiales, proponer actividades y abrir espacios de reflexión. La experiencia combina lectura, observación, práctica y diálogo.</p></article>
<article class="theory-card"><span class="num">COMPROMISO</span><h3>Contenido responsable y ecuatoriano</h3><p>El enfoque del proyecto es la Lengua de Señas Ecuatoriana. Por ello, se priorizan fuentes y materiales de Ecuador y se procura distinguir los contenidos confirmados de aquellos que requieren revisión. Una imagen o una ilustración no debe presentarse como una seña auténtica si no ha sido verificada. El aprendizaje debe mantener respeto por las variantes, la identidad y las recomendaciones de personas sordas y docentes con experiencia en LSEC.</p></article>
<article class="theory-card"><span class="num">ACCESIBILIDAD</span><h3>Un recurso sencillo para la comunidad</h3><p>La web está construida para abrirse en un navegador y utilizarse en computadoras o dispositivos móviles. No exige crear cuentas ni ingresar datos personales, y puede proyectarse durante una clase. Algunas funciones y recursos audiovisuales necesitan conexión a internet. Su diseño busca que la navegación sea comprensible y que docentes y estudiantes encuentren con facilidad los contenidos principales.</p></article>
<article class="theory-card"><span class="num">ALCANCE</span><h3>Un punto de partida, no un curso certificado</h3><p>Esta plataforma es un apoyo introductorio y educativo. No otorga certificación de dominio de LSEC ni sustituye cursos impartidos por instructores cualificados, intérpretes profesionales o la interacción con la comunidad sorda. Aprender una lengua requiere práctica continua, retroalimentación y contacto con sus usuarios. El proyecto invita a continuar ese proceso más allá de la pantalla.</p></article>
</div>
<div class="section-head"><div><h2>Dedicatoria</h2><p>Un reconocimiento a quienes dan sentido a esta iniciativa.</p></div></div>
<div class="notice"><p><strong>Este proyecto está dedicado a las personas sordas del Ecuador</strong>, a la comunidad sorda que mantiene viva la Lengua de Señas Ecuatoriana y a quienes trabajan por una sociedad donde todas las personas puedan comunicarse, aprender y participar con dignidad. También está dedicado a los estudiantes y docentes de la Unidad Educativa San Agustín, con la esperanza de que este recurso despierte interés por aprender LSEC y contribuya a construir una escuela más consciente, cercana e inclusiva.</p></div>
<div class="section-head"><div><h2>Agradecimientos</h2><p>Reconocimiento a las personas y grupos que acompañan el proceso educativo.</p></div></div>
<div class="theory-grid">
<article class="theory-card"><span class="num">2.º TÉCNICO</span><h3>Agradecimiento al curso</h3><p>Se expresa un agradecimiento especial a los estudiantes de 2.º Técnico por formar parte de la comunidad educativa a la que está dirigida esta propuesta. Su participación, curiosidad y disposición para conocer nuevas formas de comunicación pueden ayudar a que el proyecto se convierta en una herramienta útil dentro y fuera del aula.</p></article>
<article class="theory-card"><span class="num">3.º INFORMÁTICA</span><h3>Agradecimiento al curso</h3><p>Un agradecimiento sincero al estudiante de 3.º de Informática por su enorme compromiso y entrega en la creación de esta iniciativa. Ha sido un excelente espacio para aplicar la programación y el diseño en favor de un hermoso fin social: acercar la LSEC a todos en el colegio.</p></article>
<article class="theory-card"><span class="num">COMUNIDAD EDUCATIVA</span><h3>Docentes, autoridades y familias</h3><p>Gracias a los docentes, autoridades y familias de la Unidad Educativa San Agustín por el acompañamiento que hace posible impulsar propuestas educativas. Su orientación y apoyo son importantes para que el aprendizaje de la LSEC pueda integrarse en actividades escolares y convertirse en una experiencia compartida.</p></article>
<article class="theory-card"><span class="num">COMUNIDAD SORDA</span><h3>Personas sordas e instructores de LSEC</h3><p>Se reconoce especialmente a las personas sordas, asociaciones, instructores y especialistas que conservan, enseñan, documentan y difunden la LSEC. Sus conocimientos y experiencias son fundamentales para que los materiales educativos sean respetuosos, pertinentes y fieles a la realidad lingüística del Ecuador.</p></article>
</div>
<div class="section-head"><div><h2>Un compromiso para seguir aprendiendo</h2><p>La inclusión se construye con acciones constantes.</p></div></div>
<div class="callout"><div><h3>Aprender una lengua también es aprender a escuchar y respetar.</h3><p>LSEC San Agustín invita a toda la comunidad educativa a explorar, preguntar, practicar y seguir aprendiendo junto a las personas que utilizan la Lengua de Señas Ecuatoriana.</p></div><a class="btn btn-primary" href="https://www.sanagustin.edu.ec/" target="_blank" rel="noopener">Visitar San Agustín ↗</a></div>
<div class="section-head"><div><h2>Fuentes y recursos</h2><p>Materiales para ampliar y verificar el contenido de aprendizaje.</p></div></div><div class="resource-list">${resource("Unidad Educativa San Agustín","Sitio institucional del colegio al que está dirigido este proyecto.","https://www.sanagustin.edu.ec/")}${resource("FENASEC · Federación Nacional de Personas Sordas del Ecuador","Organización nacional de referencia de la comunidad sorda.", "https://fenasec-ecu.wixsite.com/fenasec/bienvenido-a-web")}${resource("WikiInclusion · Tutoriales LSEC","Videos por temas: alfabeto, saludos, familia, colores y más.",WIKINCLUSION)}${resource("MILSEC · Recursos educativos y audiovisuales","Producción de materiales educativos y multimedia en LSEC.","https://milsecoficial.org/produccion/")}</div>`}
function render(){const pages={inicio:home,alfabeto:alphabetPage,videoteca:videoPage,teoria:theoryPage,actividades:activities,cultura,proyecto};app.innerHTML=pages[currentPage]();app.focus({preventScroll:true});}
function openModal(title,body,actions=""){let modal=document.getElementById("contentModal");if(!modal){modal=document.createElement("div");modal.id="contentModal";modal.className="modal-backdrop";modal.innerHTML='<section class="content-modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><button class="modal-close" aria-label="Cerrar">×</button><div id="modalBody"></div></section>';document.body.appendChild(modal);}modal.querySelector("#modalBody").innerHTML=`<div class="eyebrow">LSEC SAN AGUSTÍN</div><h2 id="modalTitle">${title}</h2>${body}${actions}`;modal.classList.add("show");}
function closeModal(){document.getElementById("contentModal")?.classList.remove("show")}
function showTheory(index){
 const all=getTheoryModules(),t=all[index];if(!t)return;
 const prompts=[
 "¿Qué aprendiste sobre este tema? Comparte un ejemplo de cómo se relaciona con la vida escolar.",
 "¿Qué preguntas te quedan? ¿Qué fuente ecuatoriana podríamos consultar para comprobar la información?",
 "¿Cómo podemos aplicar este conocimiento para que el aula sea más accesible y respetuosa?"
 ];
 openModal(t[1],`<p class="modal-description">${t[2]}</p><div class="notice">Idea clave: la LSEC es una lengua viva de la comunidad sorda ecuatoriana. Para aprender señas concretas, utiliza recursos producidos o validados por la comunidad y docentes competentes.</div><h3>Para conversar en clase</h3><ul class="class-prompts">${prompts.map(p=>`<li>${p}</li>`).join("")}</ul><h3>Actividad breve</h3><p class="modal-description">En parejas, anoten una idea importante del módulo, una duda que quieran investigar y una acción que pueda aplicarse en la escuela.</p>`,`<div class="button-row"><button class="btn btn-primary" data-go="cultura">Ver cultura e inclusión</button><button class="btn btn-light" onclick="window.print()">Imprimir módulo</button></div>`)
}
document.addEventListener("click",e=>{
 const mini=e.target.closest("[data-mini-choice]");if(mini){const key=mini.dataset.miniChoice;const feedback=document.querySelector(`[data-mini-feedback="${key}"]`);if(feedback){feedback.textContent=mini.dataset.feedback||"Respuesta registrada.";feedback.classList.toggle("is-correct",mini.dataset.correct==="true");feedback.classList.toggle("is-incorrect",mini.dataset.correct!=="true");}mini.parentElement.querySelectorAll("button[data-mini-choice]").forEach(b=>b.classList.toggle("selected",b===mini));return}
 const playVideo=e.target.closest("[data-play-video]");if(playVideo){const frame=playVideo.closest(".video-frame");const id=playVideo.dataset.playVideo;const title=playVideo.dataset.videoTitle||"Video LSEC";frame.innerHTML=`<iframe src="https://www.youtube-nocookie.com/embed/${id}?autoplay=1&rel=0" title="${title} en LSEC" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe><a class="video-external-fallback" href="https://www.youtube.com/watch?v=${id}" target="_blank" rel="noopener">¿No se reproduce? Abrir en YouTube ↗</a>`;return}
 const goBtn=e.target.closest("[data-go]");if(goBtn){go(goBtn.dataset.go);return}
 const nav=e.target.closest("[data-page]");if(nav){go(nav.dataset.page);return}
 const zoom=e.target.closest("[data-letter-zoom]");if(zoom){openLetterViewer(selectedLetter);return}
 const letter=e.target.closest("[data-letter]");if(letter){selectedLetter=letter.dataset.letter;render();return}
 const prev=e.target.closest("[data-letter-prev]");if(prev){selectedLetter=alphabet[Math.max(0,alphabet.indexOf(selectedLetter)-1)];render();return}
 const next=e.target.closest("[data-letter-next]");if(next){selectedLetter=alphabet[Math.min(alphabet.length-1,alphabet.indexOf(selectedLetter)+1)];render();return}
 const theoryBtn=e.target.closest("[data-theory]");if(theoryBtn){showTheory(Number(theoryBtn.dataset.theory));return}
 const videoTopic=e.target.closest("[data-video-topic]");if(videoTopic){closeModal();go("videoteca");setTimeout(()=>{const input=document.getElementById("videoSearch");if(input){input.value=videoTopic.dataset.videoTopic;input.dispatchEvent(new Event("input"));}},0);return}
 if(e.target.closest(".modal-close")||e.target.classList.contains("modal-backdrop")){closeModal();return}
 const ans=e.target.closest("[data-answer]");if(ans&&!answered){const q=activityQuestions[activityIndex],v=Number(ans.dataset.answer);answered=true;if(v===q.correct){score++;ans.classList.add("correct");document.getElementById("feedback").textContent="¡Correcto! "+q.why}else{ans.classList.add("wrong");document.querySelector(`[data-answer="${q.correct}"]`).classList.add("correct");document.getElementById("feedback").textContent="Vamos a aprender: "+q.why}document.querySelectorAll("[data-answer]").forEach(b=>b.disabled=true);document.getElementById("nextQuestion").disabled=false;return}
 if(e.target.closest("#nextQuestion")){if(activityIndex===activityQuestions.length-1){app.innerHTML=`${pageIntro("RESULTADO","¡Buen trabajo!","Terminaste el reto. Tu puntaje es ${score} de ${activityQuestions.length}. Sigue explorando la plataforma.","Actividad completada")}<div class="activity-box"><h2>${score>=Math.ceil(activityQuestions.length*0.8)?"¡Excelente trabajo!":"¡Sigue practicando!"}</h2><p class="lead">Recuerda que aprender una lengua también implica conocer y respetar a su comunidad.</p><button class="btn btn-primary" id="restartQuiz">Volver a intentar</button></div>`}else{activityIndex++;answered=false;render()}return}
 if(e.target.closest("#restartQuiz")){activityQuestions=shuffledQuestions();activityIndex=0;score=0;answered=false;render();return}
});
